// wispthread graceful shutdown
pub fn drain_connections(listener: &TcpListener, budget_ms: u64) -> usize {
    let mut drained = 0;
    while let Ok((stream, _)) = listener.accept() {
        stream.set_read_timeout(Some(std::time::Duration::from_millis(budget_ms))).ok();
        drained += 1;
    }
    drained
}
